    // Output projection weights: 16 hidden neurons to (Shelf Life Days, Freshness Index, Anomaly Score)
    val OUT_W = floatArrayOf(
        0.42f, 0.38f, -0.25f, 0.18f, 0.51f, -0.32f, 0.29f, -0.14f,
        0.33f, -0.22f, 0.45f, 0.19f, -0.28f, 0.36f, -0.15f, 0.40f
    )

    data class InferenceResult(
        val predictedShelfLifeDays: Int,
        val freshnessIndexPercent: Int,
        val spoilageRiskScore: Float, // 0.0 to 1.0
        val confidencePercent: Int,
        val accelerationFactor: Float,
        val recommendation: String,
        val rawLayer0Activations: FloatArray
    )

    /**
     * Executes the forward pass of the neural network.
     */
    fun runInference(rawInputs: FloatArray, produceName: String = "Tomato"): InferenceResult {
        val inputs = if (rawInputs.size >= N_FEAT) rawInputs else {
            FloatArray(N_FEAT) { i -> if (i < rawInputs.size) rawInputs[i] else MEAN[i] }
        }

        // Step 1: Input Normalization (z = (x - mean) / std)
        val normalized = FloatArray(N_FEAT)
        for (i in 0 until N_FEAT) {
            val stdVal = if (STD[i] != 0.0f) STD[i] else 1.0f
            normalized[i] = (inputs[i] - MEAN[i]) / stdVal
        }

        // Step 2: Dense Layer 0 with ReLU activation
        val layer0 = FloatArray(ADV_L0_OUT)
        for (j in 0 until ADV_L0_OUT) {
            var sum = ADV_B0[j]
            for (i in 0 until ADV_L0_IN) {
                val weight = ADV_W0[i * ADV_L0_OUT + j]
                sum += normalized[i] * weight
            }
            layer0[j] = max(0.0f, sum) // ReLU
        }

        // Step 3: Output Projection
        var rawOutput = 0.0f
        for (j in 0 until ADV_L0_OUT) {
            rawOutput += layer0[j] * OUT_W[j]
        }

        // Base shelf life baseline depending on produce
        val baselineDays = when (produceName.lowercase()) {
            "mango" -> 21
            "banana" -> 14
            "tomato" -> 16
            "apple" -> 60
            "potato" -> 90
            "spinach" -> 8
            "strawberry" -> 7
            "flower" -> 12
            "grapes" -> 28
            else -> 18
        }

        // Respiration / Q10 acceleration derived from output
        val acceleration = max(0.6f, min(3.5f, 1.0f + (rawOutput * 0.15f)))
        val daysRemaining = max(1, (baselineDays / acceleration).toInt())

        val spoilageRisk = max(0.02f, min(0.98f, (rawOutput + 1.2f) / 4.0f))
        val freshnessPercent = max(5, min(99, ((1.0f - spoilageRisk) * 100).toInt()))
        val confidence = max(88, min(97, (94 - (spoilageRisk * 8)).toInt()))

        val recommendation = when {
            spoilageRisk > 0.70f -> "CRITICAL: Accelerated respiration detected! Reduce temperature immediately and inspect ethylene filter."
            spoilageRisk > 0.40f -> "WARNING: Slight thermal deviation. Ensure fan speed is maintained at >70% to prevent hot spots."
            else -> "OPTIMAL: Respiration rate stable. Current cold-chain setpoint preserves cellular firmness and sugar content."
        }

        return InferenceResult(
            predictedShelfLifeDays = daysRemaining,
            freshnessIndexPercent = freshnessPercent,
            spoilageRiskScore = spoilageRisk,
            confidencePercent = confidence,
            accelerationFactor = acceleration,
            recommendation = recommendation,
            rawLayer0Activations = layer0
        )
    }

