// Inference function for embedded C runtime
float visionx_edge_predict(const float* raw_inputs, float* out_spoilage_score) {
    float norm[15];
    for (int i = 0; i < 15; i++) {
        norm[i] = (raw_inputs[i] - MEAN[i]) / STD[i];
    }
    
    float l0[16];
    for (int j = 0; j < 16; j++) {
        float s = ADV_B0[j];
        for (int i = 0; i < 15; i++) {
            s += norm[i] * ADV_W0[i * 16 + j];
        }
        l0[j] = (s > 0.0f) ? s : 0.0f; // ReLU
    }
    
    float output = 0.0f;
    for (int j = 0; j < 16; j++) {
        output += l0[j] * OUT_W[j];
    }
    
    if (out_spoilage_score) {
        *out_spoilage_score = (output + 1.2f) / 4.0f;
    }
